/**
 * Run a probe request to completion, collecting its usage and finish reason.
 *
 * Marks the request in `__probeRequests` so the capture observer skips it and
 * never pollutes the "most recent real request" record.
 *
 * @param {object} llm - The LLM runtime with a `stream(options)` method.
 * @param {object} options - The assembled probe request.
 * @returns {Promise<{ usage: object | null, finish: object | null }>} The last
 *   `usage` chunk and the `finish` reason observed, either of which may be null.
 */
async function __runProbe(llm, options) {
  let usage = null
  let finish = null
  __probeRequests.add(options)
  try {
    for await (const chunk of llm.stream(options)) {
      if (chunk && chunk.type === 'usage') usage = chunk.usage
      else if (chunk && chunk.type === 'finish') finish = chunk.reason
    }
  } finally {
    __probeRequests.delete(options)
  }
  return { usage, finish }
}


// ===== src/core/report.js =====
/**
 * Formats probe usage into a human-readable report.
 */

/**
 * Render a finish reason as a short human-readable label.
 *
 * @param {object | undefined} reason - The stream `finish` reason.
 * @returns {string} A localized label describing why generation stopped.
 */
function __finishLabel(reason) {
  if (!reason) return '未知'
  if (reason.kind === 'stop') return '正常结束'
  if (reason.kind === 'max-tokens') return '达到最大输出 token'
  if (reason.kind === 'error') {
    let failureMessage = '未知'
    if (reason.failure && reason.failure.message) failureMessage = reason.failure.message
    return '错误: ' + failureMessage
  }
  return reason.kind
}

/**
 * Turn a probe outcome into a command result object.
 *
 * @param {object} result - `{ mode, usage, finish, lastUsage, error? }`.
 * @returns {{ kind: 'success', text: string } | { kind: 'error', text: string }}
 *   The rendered report as a slash-command result.
 */
function __formatReport(result) {
  if (result.error) {
    return { kind: 'error', text: '探针执行失败: ' + result.error }
  }
  const u = result.usage
  if (!u) {
    return { kind: 'error', text: '探针未返回 usage（可能被上游终止或超时）。' }
  }
  const hit = u.cacheReadTokens || 0
  const miss = u.inputTokens || 0
  const total = hit + miss
  const ratio = total > 0 ? hit / total : 0
  const pct = (ratio * 100).toFixed(1)

  let verdict
  if (hit === 0) verdict = '❌ 缓存已失效（前缀完全未命中）'
  else if (ratio >= 0.9) verdict = '✅ 缓存存活（头部几乎完整命中）'
  else if (ratio >= 0.5) verdict = '🟡 缓存部分存活（头部命中，尾部已失效）'
  else verdict = '🟠 缓存大部分失效（仅少量命中）'

  const lines = [
    'DeepSeek 缓存探针结果（mode=' + result.mode + '）',
    '- 前缀 token 总数：' + total,
    '- 缓存命中：' + hit + ' token（' + pct + '%）',
    '- 缓存未命中：' + miss + ' token',
    '- 结束原因：' + __finishLabel(result.finish),
    '- 结论：' + verdict,
    ''
  ]
  const last = result.lastUsage
  if (last) {
    const lh = last.cacheReadTokens || 0
    const lm = last.inputTokens || 0
    const lt = lh + lm
    if (lt > 0) lines.push('（参考：最近一次真实请求命中 ' + lh + '/' + lt + ' token）')
  }
  return { kind: 'success', text: lines.join('\n') }
}


// ===== src/core/reconstruct.js =====
/**
 * Reconstruct the most recent real request from a live session's durable log.
 *
 * `__lastRequest` only records requests that flow through `llm/stream` in THIS
 * process. A resumed ("old") conversation loads its history from storage, so on
 * the first `/cache-check` before any new turn the in-memory capture is empty.
 *
 * DSH persists every request in reconstructable form, so the same facts the
 * capture observer would have recorded can be rebuilt from the session:
 * - `session.deriveMessages()`     -> the exact ordered message history
 * - `session.requestHeader()`      -> the latest folded request/header snapshot
 *                                    (provider/model/system/tools/sampling)
 * - `session.requestContext()`     -> the latest route metadata (fallback)
 * - the last `assistant/message`   -> the most recent token usage (fallback)
 */

/**
 * Return the most recent assistant usage recorded in a session log.
 *
 * Scans backwards so a long conversation costs O(tail) and always returns the
 * latest successful step's accounting, even across process restarts.
 *
 * @param {object} session - The live session (`invocation.agent.session`).
 * @returns {object | null} The last `usage` payload, or `null` when none.
 */
function __lastUsageFromSession(session) {
  const events = session.events
  for (let i = events.length - 1; i >= 0; i--) {
    const event = events[i]
    if (event && event.type === 'assistant/message' && event.data && event.data.usage) {
      return event.data.usage
    }
  }
  return null
}

/**
 * Rebuild the last real request snapshot from a live session.
 *
 * The returned object has the same shape as the capture observer's snapshot
 * (`provider/model/system/messages/tools/temperature/stop/reasoningEffort`), so
 * `__buildProbeRequest` consumes it unchanged.
 *
 * @param {object} session - The live session to reconstruct from.
 * @param {object | undefined} agentOptions - `agent.options` fallback for the
 *   provider/model route when no request header or route context exists yet.
 * @returns {object | null} The reconstructed snapshot, or `null` when the
 *   session has no message history or no resolvable provider/model route.
 */
function __reconstructRequest(session, agentOptions) {
  const messages = session.deriveMessages()
  if (!messages.length) return null

  const header = session.requestHeader()
  const context = session.requestContext()
  const config = header && header.config ? header.config : {}
  const opts = agentOptions || {}

  const provider = config.provider || (context && context.provider) || opts.provider
  const model = config.model || (context && context.model) || opts.model
  if (!provider || !model) return null

  return {
    provider: provider,
    model: model,
    system: header ? header.system : undefined,
    messages: messages,
    tools: header ? header.tools : undefined,
    temperature: config.temperature,
    stop: config.stop,
    reasoningEffort: config.reasoningEffort
  }
}


